'use strict';

// MODULES //

var tape = require( 'tape' );
var isnanf = require( '@stdlib/math/base/assert/is-nanf' );
var isPositiveZerof = require( '@stdlib/math/base/assert/is-positive-zerof' );
var PINF = require( '@stdlib/constants/float32/pinf' );
var NINF = require( '@stdlib/constants/float32/ninf' );
var f32 = require( '@stdlib/number/float64/base/to-float32' );
var isAlmostSameValuef = require( '@stdlib/number/float32/base/assert/is-almost-same-value' );
var erfcinvf = require( './../lib' );


// FIXTURES //

var medium = require( './fixtures/julia/medium.json' );
var small = require( './fixtures/julia/small.json' );
var smaller = require( './fixtures/julia/smaller.json' );
var tiny = require( './fixtures/julia/tiny.json' );
var subnormal = require( './fixtures/julia/subnormal.json' );
var large = require( './fixtures/julia/large.json' );
var larger = require( './fixtures/julia/larger.json' );
var huge = require( './fixtures/julia/huge.json' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof erfcinvf, 'function', 'main export is a function' );
	t.end();
});

tape( 'if provided `NaN`, the function returns `NaN`', function test( t ) {
	var v = erfcinvf( NaN );
	t.strictEqual( isnanf( v ), true, 'returns expected value' );
	t.end();
});

tape( 'if provided `0`, the function returns `+infinity`', function test( t ) {
	var v = erfcinvf( 0.0 );
	t.strictEqual( v, PINF, 'returns expected value' );
	t.end();
});

tape( 'if provided `2`, the function returns `-infinity`', function test( t ) {
	var v = erfcinvf( 2.0 );
	t.strictEqual( v, NINF, 'returns expected value' );
	t.end();
});

tape( 'if provided `1`, the function returns `0`', function test( t ) {
	var v = erfcinvf( 1.0 );
	t.strictEqual( isPositiveZerof( v ), true, 'returns expected value' );
	t.end();
});

tape( 'if provided a value which is either less than `0` or greater than `2`, the function returns `NaN`', function test( t ) {
	var values;
	var v;
	var i;

	values = [
		3.14,
		-3.14,
		2.5,
		-0.5,
		PINF,
		NINF
	];

	for ( i = 0; i < values.length; i++ ) {
		v = erfcinvf( values[ i ] );
		t.strictEqual( isnanf( v ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'the function evaluates the inverse complementary error function for `x` (medium values)', function test( t ) {
	var expected;
	var x;
	var y;
	var e;
	var i;

	expected = medium.expected;
	x = medium.x;
	for ( i = 0; i < x.length; i++ ) {
		y = erfcinvf( x[ i ] );
		e = f32( expected[ i ] );
		t.strictEqual( isAlmostSameValuef( y, e, 3 ), true, 'returns expected value' );
	}
	t.end();
});

